"""JSI protocol connection implementations."""

import logging
import math
import struct
import typing
import weakref

from jsilib import _utils
from jsilib._compat import asyncio
from jsilib.aio import helpers
from jsilib.aio.interface import IReactor
from jsilib.base import IClosable
from jsilib.transport import exc as transport_exc
from jsilib.transport.frames import Ack, Chunk, Frame, Nack, Ping, Pong, Term
from jsilib.transport.interface import ITransportConnection

from . import _globals, _utils as _jsi_utils
from . import exc as jsi_exc
from ._state_machine import TransferStateMachine
from ._frame_reader import FrameReader
from ._keep_alive_watchdog import KeepAliveWatchdog
from ._outgoing_message import JSISwimOutgoingMessage
from ._incoming_message import JSISwimIncomingMessage
from .interface import IJSIConnection, IJSIMessage
from .settings import Settings

__all__ = export = _utils.ExportList()

logger = logging.getLogger(_globals.LOGGER_NAME)


@export
class JSIConnection(IJSIConnection):
    """Implementation of the JSI protocol.

    :param reactor:
        Reactor to be used

    :param transport:
        Transport connection to be used as a backend.

        It will be a source of incoming frames and target for outgoing
        frames.

    :param settings:
        Settings for the JSI protocol.

        See :class:`Settings` for more information.
    """

    def __init__(self, reactor: IReactor, transport: ITransportConnection, settings: Settings = Settings()):

        @_utils.log_exceptions(logger)
        async def frame_reader():

            def handle_ack_nack_frame(frame: Nack) -> bool:
                outgoing_transfer = self._outgoing_transfers.get(frame.message_id)
                if outgoing_transfer is None:
                    return False
                outgoing_transfer.set_ack_or_nack(frame)
                return True

            def handle_chunk_frame(frame: Chunk) -> bool:
                message_id = frame.message_id
                if message_id not in self._incoming_transfers:
                    self._incoming_transfers[message_id] = transfer =\
                        self._IncomingTransfer(self, message_id, frame.message_size)
                    self._incoming_message_queue.put_nowait(transfer)
                self._incoming_transfers[message_id].set_chunk(frame)
                return True

            def handle_ping_frame(frame: Ping) -> bool:
                transport.send_nowait(Pong(frame.ping_id))
                return True

            def handle_pong_frame(frame: Pong) -> bool:
                if frame.ping_id not in self._pending_ping_frames:
                    return False
                del self._pending_ping_frames[frame.ping_id]
                return True

            def dispatch_frame(frame: Frame):
                handled = False
                if frame.type in (Frame.Type.ACK, Frame.Type.NACK):
                    handled = handle_ack_nack_frame(frame)
                elif frame.type == Frame.Type.CHUNK:
                    handled = handle_chunk_frame(frame)
                elif frame.type == Frame.Type.PING:
                    handled = handle_ping_frame(frame)
                elif frame.type == Frame.Type.PONG:
                    handled = handle_pong_frame(frame)
                elif frame.type == Frame.Type.TERM:
                    logger.info(
                        '[%s] Received TERM frame from the remote peer - closing connection on this end...',
                        _utils.get_obj_addr(self)
                    )
                    self._terminated_by_peer = True
                    self._reactor.run(self._close_with_exc(jsi_exc.ConnectionClosedByPeer()))
                    return
                if not handled:
                    logger.warning('[%s] The frame was not handled: %r', _utils.get_obj_addr(self), frame)

            while not transport.is_closed():
                try:
                    dispatch_frame(await transport.recv())
                except transport_exc.ConnectionClosedError:
                    logger.info(
                        '[%s] Transport was closed - closing connection on this end...', _utils.get_obj_addr(self)
                    )
                    self._reactor.run(self._close_with_exc(jsi_exc.ConnectionClosedByTransport()))
                    break

        self._reactor = reactor
        self._transport = transport
        self._settings = settings
        self._closed = False
        self._close_exc = None
        self._terminated_by_peer = False
        self._outgoing_transfers = {}
        self._incoming_transfers = {}
        self._incoming_message_queue: asyncio.Queue[typing.Optional[JSIConnection._IncomingTransfer]] = asyncio.Queue()
        self._frame_reader_task = reactor.run(frame_reader())
        self._pending_ping_frames = {}
        self._ping_task_id = self._reactor.call_later(self._settings.ping_idle_time, self._send_next_ping)

    def _send_next_ping(self) -> int:
        ping = Ping(_utils.next_unique_id(Ping))
        self._pending_ping_frames[ping.ping_id] = ping
        if len(self._pending_ping_frames) > self._settings.ping_loss_threshold:
            logger.warning(
                '[%s] Exceeded ping loss threshold with %d unreplied ping(-s) - closing connection on this end...',
                _utils.get_obj_addr(self), self._settings.ping_loss_threshold + 1
            )
            self._reactor.run(self._close_with_exc(jsi_exc.ConnectionClosedByPingLoss()))
        elif self._transport.is_closed():
            self._reactor.run(self._close_with_exc(jsi_exc.ConnectionClosedByTransport()))
        else:
            self._transport.send_nowait(ping)
            self._ping_task_id = self._reactor.call_later(self._settings.ping_idle_time, self._send_next_ping)

    @property
    def incoming_transfers_count(self) -> int:
        return len(self._incoming_transfers)

    @property
    def outgoing_transfers_count(self) -> int:
        return len(self._outgoing_transfers)

    def is_closed(self) -> bool:
        return self._closed

    async def _close_with_exc(self, exc: jsi_exc.ConnectionClosedError):
        self._close_exc = exc
        await self.close()

    def _raise_close_exc(self):
        if self._close_exc is not None:
            raise self._close_exc
        raise jsi_exc.ConnectionClosedError()

    async def close(self):
        if not self._closed:
            self._closed = True
            logger.debug(
                '[%s] Closing connection with %d outgoing and %d incoming transfers...', _utils.get_obj_addr(self),
                self.outgoing_transfers_count, self.incoming_transfers_count
            )
            self._incoming_message_queue.put_nowait(None)  # To force recv() wakeup and raise ConnectionClosedError
            self._close_transfers(self._incoming_transfers)
            self._close_transfers(self._outgoing_transfers)
            await self._send_term_frame_to_peer()
            await self._frame_reader_task.cancel()
            logger.info('[%s] Connection closed.', _utils.get_obj_addr(self))

    def _close_transfers(self, transfers: dict):
        while transfers:
            _, transfer = transfers.popitem()
            self._reactor.run(transfer.close())

    async def _send_term_frame_to_peer(self):
        if not isinstance(self._close_exc, jsi_exc.ConnectionClosedByPeer):
            try:
                await self._transport.send(Term())
            except transport_exc.ConnectionClosedError:
                pass

    async def send(self, message: IJSIMessage):
        if self._closed:
            return self._raise_close_exc()
        index = 0
        message_id = _utils.next_unique_id(IJSIMessage, start=0, step=2)
        logger.debug('[%s] > %r', _utils.get_obj_addr(self), message)
        self._outgoing_transfers[message_id] = transfer = self._OutgoingTransfer(message_id)
        try:
            while True:
                chunk = await helpers.read_all(message, min(message.bytes_left(), self._settings.chunk_size))
                chunk_frame = Chunk(message_id, index, message.size(), chunk)
                index += 1
                transfer.set_chunk(chunk_frame)
                await self._transport.send(chunk_frame)
                frame = await transfer.get_ack_or_nack()
                if frame is None:
                    return self._raise_close_exc()
                if message.bytes_left() == 0:
                    break
        finally:
            self._outgoing_transfers.pop(message_id, None)

    async def recv(self) -> IJSIMessage:
        if self._closed:
            return self._raise_close_exc()
        data = await self._incoming_message_queue.get()
        if data is None:
            return self._raise_close_exc()
        logger.debug('[%s] < %r', _utils.get_obj_addr(self), data)
        if data.bytes_left() == 0:
            self._incoming_transfers.pop(data.id, None)
        return data

    class _WeakOwnerMixin:

        @property
        def _owner(self) -> 'JSIConnection':
            return self.__owner()

        @_owner.setter
        def _owner(self, value: 'JSIConnection'):
            self.__owner = weakref.ref(value)

    class _OutgoingTransfer(IClosable):

        def __init__(self, message_id: int):
            self._message_id = message_id
            self._closed = False
            self._sem = asyncio.Semaphore(0)
            self._sm = TransferStateMachine()

        def set_chunk(self, frame: Chunk):
            self._sm.dispatch(frame)

        def set_ack_or_nack(self, frame: typing.Union[Ack, Nack, None]):
            self._ack_or_nack = frame
            self._sem.release()

        def is_closed(self) -> bool:
            return self._closed

        async def close(self):
            if not self._closed:
                self._closed = True
                self.set_ack_or_nack(None)

        async def get_ack_or_nack(self) -> typing.Union[Ack, Nack, None]:
            await self._sem.acquire()
            if self._ack_or_nack is None:
                return self._ack_or_nack
            self._sm.dispatch(self._ack_or_nack)
            return self._ack_or_nack

    class _IncomingTransfer(_WeakOwnerMixin, IJSIMessage):

        def __init__(self, owner: 'JSIConnection', message_id: int, message_size: int):
            self._owner = owner
            self._message_id = message_id
            self._message_size = message_size
            self._bytes_left = message_size
            self._transport = owner._transport
            self._sm = TransferStateMachine()
            self._chunk_queue: asyncio.Queue[Chunk] = asyncio.Queue()
            self._read_buffer = b''
            self._closed = False

        @property
        def id(self) -> int:
            return self._message_id

        def set_chunk(self, frame: Chunk):
            self._sm.dispatch(frame)
            if len(frame.payload) > 0:
                self._chunk_queue.put_nowait(frame)
            else:
                ack = Ack.from_chunk(frame)
                self._sm.dispatch(ack)
                self._transport.send_nowait(ack)

        def size(self) -> int:
            return self._message_size

        def bytes_left(self) -> int:
            return self._bytes_left

        def is_closed(self) -> bool:
            return self._closed

        async def close(self):
            nack = Nack(self._message_id, self._sm.current_chunk.index, b'Transfer terminated by peer')
            await self._transport.send(nack)
            self._owner._incoming_transfers.pop(self._message_id, None)
            self._closed = True

        async def read(self, count: int) -> bytes:
            if not self._read_buffer:
                chunk = await self._chunk_queue.get()
                self._read_buffer += chunk.payload
                ack = Ack.from_chunk(chunk)
                self._sm.dispatch(ack)
                self._transport.send_nowait(ack)
            out = self._read_buffer[:count]
            self._read_buffer = self._read_buffer[count:]
            self._bytes_left -= len(out)
            if self._bytes_left == 0:
                self._owner._incoming_transfers.pop(self._message_id, None)
            return out


@export
class JSISwimConnection(IJSIConnection):
    """JSI connection with SWIM-compatible mode enabled.

    This class is a temporary solution to enable multiple chunk transfers to
    and from SWIM, as SWIM has JSI protocol implemented in the wrong way and
    "normal" connection will simply not work with multi chunk transfers.
    """

    def __init__(self,
                 reactor: IReactor,
                 transport_connection: ITransportConnection,
                 settings: Settings = Settings()):
        self._reactor = reactor
        self._transport_connection = transport_connection
        self._settings = settings
        self._closed = False
        self._frame_reader = FrameReader(reactor, transport_connection)
        self._frame_reader.register_frame_handler(Ack, self._on_ack_or_nack_received)
        self._frame_reader.register_frame_handler(Nack, self._on_ack_or_nack_received)
        self._frame_reader.register_frame_handler(Chunk, self._on_chunk_received)
        self._frame_reader.register_frame_handler(Term, self._on_term_received)
        self._frame_reader.register_frame_handler(Ping, self._on_ping_received)
        self._frame_reader.register_frame_handler(Pong, self._on_pong_received)
        self._frame_reader.register_connection_closed_handler(self._on_transport_connection_closed)
        self._frame_reader.start()
        self._keep_alive_watchdog = KeepAliveWatchdog(reactor, transport_connection, settings)
        self._keep_alive_watchdog.register_connection_lost_handler(self._on_ping_failed)
        self._keep_alive_watchdog.start()
        self._incoming_message_queue: asyncio.Queue[typing.Optional[JSISwimConnection._IncomingTransfer]] = asyncio.Queue()
        self._outgoing_messages: typing.Dict[int, JSISwimOutgoingMessage] = {}
        self._incoming_messages: typing.Dict[int, JSISwimIncomingMessage] = {}
        self._term_received = False
        self._close_exc = None

    def _on_ack_or_nack_received(self, ack_or_nack: typing.Union[Ack, Nack]):
        outgoing = self._outgoing_messages.get(ack_or_nack.message_id)
        if outgoing is None:
            return False
        outgoing.dispatch_ack_or_nack(ack_or_nack)
        self._keep_alive_watchdog.restart()
        return True

    def _on_chunk_received(self, chunk: Chunk):
        if chunk.message_id not in self._incoming_messages:
            #: NOTE: It is assumed that SWIM is sending same sized chunks, each of
            # same size as first chunk (besides last one which, of course, will
            # be smaller)
            max_chunk_size = len(chunk.payload)
            header_size, = struct.unpack("!I", chunk.payload[:4])
            incoming_message = JSISwimIncomingMessage(chunk.message_id, chunk.message_size, max_chunk_size, header_size)
            incoming_message.register_completion_handler(self._on_incoming_message_transfer_complete)
            incoming_message.register_frame_handler(self._transport_connection.send_nowait)
            self._incoming_messages[chunk.message_id] = incoming_message
            self._incoming_message_queue.put_nowait(incoming_message)
        self._incoming_messages[chunk.message_id].dispatch_chunk(chunk)
        self._keep_alive_watchdog.restart()
        return True

    def _on_term_received(self, _: Term):

        async def close():
            try:
                await self._transport_connection.send(Term())
            except transport_exc.ConnectionClosedError:
                pass
            else:
                await self._close_with_exc(jsi_exc.ConnectionClosedByPeer())

        if self._term_received:
            return False
        self._term_received = True
        self._reactor.run(close())
        self._keep_alive_watchdog.restart()
        return True

    def _on_ping_received(self, ping: Ping):
        self._transport_connection.send_nowait(Pong(ping_id=ping.ping_id))
        return True

    def _on_pong_received(self, pong: Pong):
        return self._keep_alive_watchdog.dispatch_pong(pong)

    def _on_transport_connection_closed(self):
        self._close_with_exc_nowait(jsi_exc.ConnectionClosedByTransport())

    def _on_ping_failed(self, exc: Exception):
        self._close_with_exc_nowait(exc)

    def _on_incoming_message_transfer_complete(self, message_id: int, size: int, bytes_left: int):
        self._incoming_messages.pop(message_id, None)

    def _close_with_exc_nowait(self, exc: Exception):
        self._reactor.run(self._close_with_exc(exc))

    async def _close_with_exc(self, exc: Exception):
        if not self._closed:
            self._closed = True
            self._close_exc = exc
            if not self._term_received:
                try:
                    self._transport_connection.send_nowait(Term())
                except transport_exc.ConnectionClosedError:
                    pass
            self._incoming_message_queue.put_nowait(None)  # To force recv() wakeup and raise ConnectionClosedError
            for outgoing_transfer in self._outgoing_messages.values():
                self._reactor.run(outgoing_transfer.close())
            for incoming_transfer in self._incoming_messages.values():
                self._reactor.run(incoming_transfer.close())
            self._outgoing_messages.clear()
            self._incoming_messages.clear()
            self._keep_alive_watchdog.stop()
            await self._frame_reader.close()

    def _require_not_closed(self):
        if self._closed:
            self._raise_close_exc()

    def _raise_close_exc(self):
        if self._close_exc is not None:
            raise self._close_exc
        raise jsi_exc.ConnectionClosedError()

    @property
    def incoming_transfers_count(self) -> int:
        return len(self._incoming_messages)

    @property
    def outgoing_transfers_count(self) -> int:
        return len(self._outgoing_messages)

    async def send(self, message: IJSIMessage):
        self._require_not_closed()
        logger.debug('[%s] > %r', _utils.get_obj_addr(self), message)
        header_size, = struct.unpack("!I", await helpers.read_all(message, 4))
        header = await helpers.read_all(message, header_size)
        min_chunk_size = header_size + 4 + 1  # len(HEADER) + len(HEADER_SIZE) + 1 (to allow body transfer)
        chunk_size = self._settings.chunk_size
        if chunk_size < min_chunk_size:
            logger.warning("Current chunk size is too low; overriding: %d -> %d", self._settings.chunk_size, min_chunk_size)
            chunk_size = min_chunk_size  # Header needs to be transfer repeatedly in each chunk, so let's adjust this
        outgoing = JSISwimOutgoingMessage(header, message, chunk_size)
        self._outgoing_messages[outgoing.id] = outgoing
        try:
            while True:
                chunk = await outgoing.next_chunk()
                if chunk is None:
                    break
                await self._transport_connection.send(chunk)
                ack_or_nack = await outgoing.receive_ack_or_nack()
                if ack_or_nack is None:
                    self._raise_close_exc()
        finally:
            self._outgoing_messages.pop(outgoing.id, None)

    async def recv(self) -> IJSIMessage:
        self._require_not_closed()
        message = await self._incoming_message_queue.get()
        if message is None:
            self._raise_close_exc()
        logger.debug('[%s] < %r', _utils.get_obj_addr(self), message)
        if message.bytes_left() == 0:
            self._incoming_messages.pop(message.id, None)
        return message

    async def close(self):
        await self._close_with_exc(jsi_exc.ConnectionClosedError())

    def is_closed(self) -> bool:
        return self._closed


@export
class QueueJSIConnection(IJSIConnection):
    """Implementation of the :class:`IJSIConnection`, but based on input-output
    queues.

    This is basically a helper to be used for testing upper-layer levels.

    :param reactor:
        Reactor to be used.

    :param input:
        Input queue, from which messages are read.

    :param output:
        Output queue, to which messages are written.
    """
    _close_signal = object()

    def __init__(self, reactor: IReactor, input: asyncio.Queue[IJSIMessage], output: asyncio.Queue[IJSIMessage]):
        self._reactor = reactor
        self._input = input
        self._output = output
        self._closed = False

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            self._input.put_nowait(self._close_signal)

    async def recv(self) -> IJSIMessage:
        if self._closed:
            raise jsi_exc.ConnectionClosedError(self)
        message = await self._input.get()
        if message is self._close_signal:
            raise jsi_exc.ConnectionClosedError(self)
        return message

    async def send(self, message: IJSIMessage):
        if self._closed:
            raise jsi_exc.ConnectionClosedError(self)
        self._output.put_nowait(message)
